import {displayNumber} from './number-display.js';
import {registerCatalog,t,localizedText} from './i18n.js';
import {annualTextHTML} from './annual-localization.js';
import {growthChartData} from './approved-charts.js';
registerCatalog('annualRevenueGrowth',{en:{fcfTitle:'Year-by-year unlevered FCF (FCFF) growth',fcfMethod:'FCFF = after-tax operating profit − net reinvestment. Percent growth is shown only when both current and prior FCFF are positive; zero and negative transitions are labeled directly.',fcfBaseline:'Year 1 has no comparable source FCFF anchor; growth starts with the next forecast year.',ocf:'Operating cash flow (OCF) growth is unavailable: this model does not forecast OCF separately. After-tax operating profit is not OCF, and net reinvestment is not cash capital expenditure.',negative:'Turns negative',loss:'Still negative',recovery:'Turns positive',toZero:'Reaches zero',fromZero:'From zero',missingBase:'No prior value',fcfGrowth:'FCFF growth / transition',title:'Year-by-year revenue growth',scope:'Every forecast year · {years} years',method:'Growth = current-year revenue ÷ previous-year revenue − 1. Forecast assumptions, not reported results.',baseline:'Year 1 comparison base',scale:'Common scale: {min} to {max} · zero baseline shown',year:'Year {year}',value:'Year {year}: {value}',unavailable:'Unavailable',missing:'Growth is unavailable when prior revenue is zero, negative or missing.',table:'Exact annual growth values',growth:'Revenue growth',terminal:'Stable terminal assumption: {value}. The chart preserves each actual forecast year, including any difference from this assumption.'},'zh-Hans':{fcfTitle:'逐年无杠杆自由现金流（FCFF）增长率',fcfMethod:'FCFF = 税后经营利润 − 净再投资。仅在当年和上年 FCFF 均为正时显示增长率；零值及负值变化直接标注状态。',fcfBaseline:'第 1 年缺少可比的来源 FCFF 基准；从下一个预测年份开始比较。',ocf:'经营现金流（OCF）增长率不可用：本模型未单独预测 OCF。税后经营利润不等于 OCF，净再投资也不等于现金资本支出。',negative:'转为负值',loss:'仍为负值',recovery:'转为正值',toZero:'回到零',fromZero:'从零起步',missingBase:'无上年值',fcfGrowth:'FCFF 增长率 / 状态变化',title:'逐年收入增长率',scope:'全部预测年份 · {years} 年',method:'增长率 = 当年收入 ÷ 上年收入 − 1。以下为预测假设，并非已报告业绩。',baseline:'第 1 年的比较基准',scale:'统一刻度：{min} 至 {max} · 显示零基线',year:'第 {year} 年',value:'第 {year} 年：{value}',unavailable:'不可用',missing:'上年收入为零、负值或缺失时，增长率不可用。',table:'各年增长率明细',growth:'收入增长率',terminal:'稳定期终值增长假设：{value}。图表保留各预测年份的实际计算值，包括与该假设的差异。'}});
// Complete messages keep translated statuses out of frozen interpolation parameters.
registerCatalog('annualGrowthStatus', {en:{missingBase:'Year {year}: No prior value',loss:'Year {year}: Still negative',recovery:'Year {year}: Turns positive',negative:'Year {year}: Turns negative',toZero:'Year {year}: Reaches zero',fromZero:'Year {year}: From zero',unavailable:'Year {year}: Unavailable'},'zh-Hans':{missingBase:'第 {year} 年：无上年值',loss:'第 {year} 年：仍为负值',recovery:'第 {year} 年：转为正值',negative:'第 {year} 年：转为负值',toZero:'第 {year} 年：回到零',fromZero:'第 {year} 年：从零起步',unavailable:'第 {year} 年：不可用'}});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(value,digits=2)=>Number.isFinite(value)?displayNumber(value*100,digits)+'%':t('annualRevenueGrowth.unavailable');
const text=(key,params)=>localizedText('annualRevenueGrowth.'+key,params);
/** Presentation only. Never substitute rounded inputs or an independently generated growth curve. */
export function annualRevenueGrowthData(rows,anchorRevenue){
 let previous=anchorRevenue;
 return (rows||[]).map(row=>{const priorRevenue=previous;previous=row.revenue;const growth=Number.isFinite(priorRevenue)&&priorRevenue>0&&Number.isFinite(row.revenue)?row.revenue/priorRevenue-1:null;return {year:row.year,period:row.period,revenue:row.revenue,priorRevenue,growth:Number.isFinite(growth)?growth:null};});
}
export function annualRevenueGrowthChartHTML(rows,{anchor={},terminalGrowth,id='annual-revenue-growth'}={}){
 return growthHTML(annualRevenueGrowthData(rows,anchor.revenue),{anchor,terminalGrowth,id});
}
export function annualFCFFGrowthData(rows){
 let previous=null;return (rows||[]).map(row=>{const prior=previous;previous=row.fcff;const valid=Number.isFinite(prior)&&Number.isFinite(row.fcff);const raw=valid&&prior>0&&row.fcff>0?row.fcff/prior-1:null;const status=!valid?'missingBase':prior>0?(row.fcff<0?'negative':row.fcff===0?'toZero':null):prior===0?(row.fcff===0?'toZero':'fromZero'):row.fcff>0?'recovery':row.fcff===0?'toZero':'loss';return {year:row.year,growth:Number.isFinite(raw)?raw:null,status};});
}
export function annualFCFFGrowthChartHTML(rows){return growthHTML(annualFCFFGrowthData(rows),{id:'annual-fcff-growth',cashFlow:true});}
function growthHTML(points,{anchor={},terminalGrowth,id,cashFlow=false}){
 if(!points.length)return '';
 const titleKey=cashFlow?'fcfTitle':'title';
 const pointHTML=(p,digits=2)=>p.status?text(p.status):p.growth===null?text('unavailable'):fmt(p.growth,digits);
 const labelKey=p=>p.status?'annualGrowthStatus.'+p.status:p.growth===null?'annualGrowthStatus.unavailable':'annualRevenueGrowth.value';
 const labelParams=p=>p.status||p.growth===null?{year:p.year}:{year:p.year,value:fmt(p.growth,6)};
 // Reuse the approved chart's common signed scale, preserving missing values separately.
 const scale=growthChartData(points.map((p,i)=>({year:i+1,growth:p.growth??0})),{stableYear:points.length});
 const range=scale.max-scale.min;
 return `<section class="annual-revenue-growth approved-growth-path" aria-labelledby="${id}-title"><div class="approved-plot-heading"><h3 id="${id}-title">${text(titleKey)}</h3><span>${text('scope',{years:points.length})}</span></div><p class="approved-scale-note">${text('scale',{min:fmt(scale.min/100),max:fmt(scale.max/100)})}</p><div class="approved-growth-bars annual-revenue-growth-bars" role="list">${points.map(p=>{const value=p.growth===null?null:p.growth*100,height=value===null?0:Math.abs(value)/range*100,bottom=value!==null&&value<0?scale.zero-height:scale.zero,label=t(labelKey(p),labelParams(p));return `<div class="approved-growth-column" role="listitem" tabindex="0" data-annual-growth-year="${p.year}" aria-label="${esc(label)}" title="${esc(label)}" data-i18n-title="${labelKey(p)}" data-i18n-aria-label="${labelKey(p)}" data-i18n-params="${esc(JSON.stringify(labelParams(p)))}" style="--growth-zero:${scale.zero}%"><div class="approved-growth-track" aria-hidden="true"><span class="approved-growth-bar" style="height:${height}%;bottom:${bottom}%;transform-origin:${value<0?'top':'bottom'}"></span><span class="approved-growth-value" style="bottom:${value!==null&&value>=0?scale.zero+height:scale.zero}%">${p.growth===null?'—':fmt(p.growth)}</span></div><span class="approved-growth-year">${text('year',{year:p.year})}</span>${p.status?`<span class="annual-growth-status">${pointHTML(p)}</span>`:''}</div>`;}).join('')}</div><p class="micro">${text(cashFlow?'fcfMethod':'method')}</p><p class="micro">${cashFlow?text('fcfBaseline'):text('baseline')+': '+esc(anchor.period||'')+' · '+annualTextHTML(anchor.classification||anchor.kind||'')+'.'}</p>${Number.isFinite(terminalGrowth)?`<p class="micro">${text('terminal',{value:fmt(terminalGrowth)})}</p>`:''}${!cashFlow&&points.some(p=>p.growth===null)?`<p class="micro">${text('missing')}</p>`:''}<details class="annual-growth-values"><summary>${text('table')}</summary><table><caption>${text(titleKey)}</caption><thead><tr><th scope="col">${text('year',{year:''})}</th><th scope="col">${text(cashFlow?'fcfGrowth':'growth')}</th></tr></thead><tbody>${points.map(p=>`<tr><th scope="row">${text('year',{year:p.year})}</th><td>${pointHTML(p,6)}</td></tr>`).join('')}</tbody></table></details>${cashFlow?`<p class="micro annual-ocf-note">${text('ocf')}</p>`:''}</section>`;
}
